def solve(inputs: dict) -> float:
    # Extract parameters
    x = inputs['x']
    steps = inputs['steps']
    c = inputs['c']
    mod = inputs['mod']

    # Iterate the map x -> (x^2 + c) mod mod for 'steps' iterations
