    exponent = inputs['exponent']
    mod = inputs['mod']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices mod p"""
        n = len(A)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, exp, mod):
        """Compute M^exp mod p using fast exponentiation"""
        n = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]  # Copy of M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    result_matrix = matrix_pow(matrix, exponent, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)

    return float(total)

